const a = msg.req.params.action;
const b = msg.payload || {};
if (a === 'start') msg.payload = {kind:'start', valve1:b.valve1 === true, valve2:b.valve2 === true};
else if (a === 'stop') msg.payload = {kind:'stop'};
else if (a === 'tick') msg.payload = {kind:'tick'};
else { msg.statusCode = 400; msg.payload = {error:'action must be start, stop or tick'}; return [null, msg]; }
return [msg, msg];
